const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>⚡ GEMINI SUPER SYSTEM // MISSION CONTROL</title>\n  <style>\n    :root {\n      --bg: #07090e;\n      --bg-alt: #0b0f19;\n      --card-bg: rgba(13, 18, 29, 0.75);\n      --card-border: rgba(255, 255, 255, 0.08);\n      --card-hover: rgba(0, 229, 255, 0.25);\n      --accent: #00e5ff;\n      --accent-glow: rgba(0, 229, 255, 0.25);\n      --accent-dim: rgba(0, 229, 255, 0.12);\n      --success: #10b981;\n      --success-dim: rgba(16, 185, 129, 0.15);\n      --warning: #f59e0b;\n      --warning-dim: rgba(245, 158, 11, 0.15);\n      --danger: #f43f5e;\n      --danger-dim: rgba(244, 63, 94, 0.15);\n      --purple: #a855f7;\n      --purple-dim: rgba(168, 85, 247, 0.15);\n      --text: #f1f5f9;\n      --text-muted: #94a3b8;\n      --text-dim: #64748b;\n      --font-sans: system-ui, -apple-system, 'Segoe UI Variable', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n      --font-mono: 'Cascadia Code', 'Consolas', 'SFMono-Regular', Menlo, Monaco, monospace;\n      --radius-sm: 6px;\n      --radius-md: 10px;\n      --radius-lg: 14px;\n      --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.3);\n      --shadow-md: 0 8px 24px -4px rgba(0, 0, 0, 0.5);\n      --shadow-glow: 0 0 20px var(--accent-glow);\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    \n    body {\n      background: var(--bg);\n      background-image: radial-gradient(circle at 50% 0%, #111a2e 0%, var(--bg) 75%);\n      color: var(--text);\n      font-family: var(--font-sans);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      -webkit-font-smoothing: antialiased;\n      line-height: 1.5;\n    }\n\n    /* Custom Scrollbar */\n    ::-webkit-scrollbar { width: 6px; height: 6px; }\n    ::-webkit-scrollbar-track { background: var(--bg); }\n    ::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 3px; }\n    ::-webkit-scrollbar-thumb:hover { background: var(--accent); }\n\n    /* Top Executive Header */\n    .header {\n      background: rgba(11, 15, 25, 0.85);\n      backdrop-filter: blur(16px);\n      border-bottom: 1px solid var(--card-border);\n      padding: 12px 24px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      position: sticky;\n      top: 0;\n      z-index: 1000;\n    }\n\n    .header-left {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n    }\n\n    .brand-logo {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      width: 36px;\n      height: 36px;\n      border-radius: var(--radius-sm);\n      background: linear-gradient(135deg, rgba(0, 229, 255, 0.2), rgba(168, 85, 247, 0.2));\n      border: 1px solid var(--accent);\n      box-shadow: 0 0 12px var(--accent-glow);\n      font-size: 18px;\n    }\n\n    .brand-title h1 {\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #fff;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .brand-title .badge {\n      font-size: 10px;\n      padding: 2px 6px;\n      border-radius: 4px;\n      background: var(--accent-dim);\n      color: var(--accent);\n      border: 1px solid var(--accent);\n      font-family: var(--font-mono);\n      font-weight: 600;\n    }\n\n    .brand-subtitle {\n      font-size: 11px;\n      color: var(--text-dim);\n      font-family: var(--font-mono);\n    }\n\n    .header-center {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n    }\n\n    .quick-vitals {\n      display: flex;\n      gap: 12px;\n      background: rgba(0, 0, 0, 0.4);\n      padding: 6px 14px;\n      border-radius: 999px;\n      border: 1px solid var(--card-border);\n      font-size: 11px;\n      font-family: var(--font-mono);\n    }\n\n    .quick-vital-item {\n      display: flex;\n      gap: 6px;\n      align-items: center;\n    }\n\n    .quick-vital-item .dim { color: var(--text-dim); }\n    .quick-vital-item .val { color: #fff; font-weight: 600; }\n\n    .header-right {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .status-pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      font-size: 11px;\n      font-family: var(--font-mono);\n      font-weight: 600;\n      padding: 5px 12px;\n      border-radius: 999px;\n      background: var(--success-dim);\n      color: var(--success);\n      border: 1px solid rgba(16, 185, 129, 0.3);\n    }\n\n    .status-dot {\n      width: 7px;\n      height: 7px;\n      border-radius: 50%;\n      background: var(--success);\n      box-shadow: 0 0 8px var(--success);\n      animation: pulse-dot 2s infinite;\n    }\n\n    @keyframes pulse-dot {\n      0%, 100% { transform: scale(1); opacity: 1; }\n      50% { transform: scale(1.3); opacity: 0.6; }\n    }\n\n    /* Primary Navigation Tab Bar */\n    .tab-bar {\n      background: rgba(7, 9, 14, 0.95);\n      border-bottom: 1px solid var(--card-border);\n      padding: 0 24px;\n      display: flex;\n      gap: 6px;\n      overflow-x: auto;\n      position: sticky;\n      top: 61px;\n      z-index: 999;\n    }\n\n    .tab-btn {\n      background: transparent;\n      border: none;\n      color: var(--text-muted);\n      font-family: var(--font-sans);\n      font-size: 12px;\n      font-weight: 600;\n      letter-spacing: 0.5px;\n      text-transform: uppercase;\n      padding: 14px 16px;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      border-bottom: 2px solid transparent;\n      transition: all 0.2s ease;\n      white-space: nowrap;\n    }\n\n    .tab-btn:hover {\n      color: #fff;\n      background: rgba(255, 255, 255, 0.03);\n    }\n\n    .tab-btn.active {\n      color: var(--accent);\n      border-bottom-color: var(--accent);\n      background: rgba(0, 229, 255, 0.05);\n    }\n\n    .tab-btn .shortcut {\n      font-size: 10px;\n      padding: 1px 5px;\n      border-radius: 3px;\n      background: rgba(255, 255, 255, 0.08);\n      color: var(--text-dim);\n      font-family: var(--font-mono);\n    }\n\n    /* Main Container */\n    .main-content {\n      padding: 24px;\n      max-width: 1600px;\n      margin: 0 auto;\n      width: 100%;\n      flex: 1;\n    }\n\n    .tab-pane {\n      display: none;\n      animation: fadeIn 0.2s ease-in-out;\n    }\n\n    .tab-pane.active {\n      display: block;\n    }\n\n    @keyframes fadeIn {\n      from { opacity: 0; transform: translateY(4px); }\n      to { opacity: 1; transform: translateY(0); }\n    }\n\n    /* Cards & Grids */\n    .grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n      gap: 16px;\n      margin-bottom: 20px;\n    }\n\n    .grid-2 {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(480px, 1fr));\n      gap: 20px;\n      margin-bottom: 20px;\n    }\n\n    .card {\n      background: var(--card-bg);\n      backdrop-filter: blur(12px);\n      border: 1px solid var(--card-border);\n      border-radius: var(--radius-md);\n      padding: 20px;\n      box-shadow: var(--shadow-sm);\n      transition: all 0.25s ease;\n      position: relative;\n      overflow: hidden;\n    }\n\n    .card:hover {\n      border-color: rgba(255, 255, 255, 0.15);\n      transform: translateY(-2px);\n      box-shadow: var(--shadow-md);\n    }\n\n    .card-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 14px;\n    }\n\n    .card-header h3 {\n      font-size: 12px;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 1px;\n      color: var(--text-muted);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .stat-val {\n      font-size: 26px;\n      font-weight: 700;\n      color: #fff;\n      font-family: var(--font-mono);\n      margin-bottom: 4px;\n    }\n\n    .stat-sub {\n      font-size: 12px;\n      color: var(--text-dim);\n    }\n\n    /* Buttons */\n    button {\n      background: var(--accent-dim);\n      border: 1px solid var(--accent);\n      color: var(--accent);\n      padding: 8px 16px;\n      border-radius: var(--radius-sm);\n      font-weight: 600;\n      cursor: pointer;\n      transition: all 0.2s;\n      font-size: 12px;\n      letter-spacing: 0.5px;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      outline: none;\n    }\n\n    button:hover {\n      background: var(--accent);\n      color: #000;\n      box-shadow: 0 0 16px var(--accent-glow);\n    }\n\n    button.secondary {\n      background: rgba(255, 255, 255, 0.04);\n      border-color: rgba(255, 255, 255, 0.12);\n      color: var(--text);\n    }\n\n    button.secondary:hover {\n      background: rgba(255, 255, 255, 0.1);\n      border-color: rgba(255, 255, 255, 0.25);\n      color: #fff;\n      box-shadow: none;\n    }\n\n    button.danger {\n      background: var(--danger-dim);\n      border-color: var(--danger);\n      color: var(--danger);\n    }\n\n    button.danger:hover {\n      background: var(--danger);\n      color: #fff;\n      box-shadow: 0 0 16px rgba(244, 63, 94, 0.4);\n    }\n\n    button.success {\n      background: var(--success-dim);\n      border-color: var(--success);\n      color: var(--success);\n    }\n\n    button.success:hover {\n      background: var(--success);\n      color: #000;\n      box-shadow: 0 0 16px rgba(16, 185, 129, 0.4);\n    }\n\n    /* Inputs & Selects */\n    .deck-input, .deck-select {\n      background: #030407;\n      border: 1px solid var(--card-border);\n      color: #fff;\n      padding: 9px 14px;\n      border-radius: var(--radius-sm);\n      font-size: 13px;\n      font-family: var(--font-sans);\n      outline: none;\n      transition: border-color 0.2s;\n    }\n\n    .deck-input:focus, .deck-select:focus {\n      border-color: var(--accent);\n      box-shadow: 0 0 8px var(--accent-glow);\n    }\n\n    /* Playbook Card Grid */\n    .playbooks-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));\n      gap: 16px;\n      margin-bottom: 24px;\n    }\n\n    .playbook-card {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-radius: var(--radius-md);\n      padding: 18px;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      transition: all 0.2s ease;\n    }\n\n    .playbook-card:hover {\n      border-color: rgba(0, 229, 255, 0.4);\n      transform: translateY(-2px);\n    }\n\n    .playbook-top {\n      margin-bottom: 14px;\n    }\n\n    .playbook-title-row {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      margin-bottom: 8px;\n    }\n\n    .playbook-icon {\n      font-size: 20px;\n    }\n\n    .playbook-title {\n      font-size: 15px;\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .playbook-category {\n      font-size: 10px;\n      padding: 2px 7px;\n      border-radius: 999px;\n      background: var(--accent-dim);\n      color: var(--accent);\n      font-family: var(--font-mono);\n      font-weight: 600;\n      margin-left: auto;\n    }\n\n    .playbook-desc {\n      font-size: 12px;\n      color: var(--text-muted);\n      line-height: 1.5;\n    }\n\n    .playbook-footer {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding-top: 12px;\n      border-top: 1px solid var(--card-border);\n    }\n\n    .playbook-tags {\n      display: flex;\n      gap: 4px;\n      flex-wrap: wrap;\n    }\n\n    .playbook-tag {\n      font-size: 10px;\n      color: var(--text-dim);\n      background: rgba(255, 255, 255, 0.04);\n      padding: 2px 6px;\n      border-radius: 4px;\n    }\n\n    /* Terminal Console */\n    .console-panel {\n      background: #030407;\n      border: 1px solid var(--card-border);\n      border-radius: var(--radius-md);\n      padding: 16px;\n      font-family: var(--font-mono);\n      font-size: 12px;\n      height: 480px;\n      overflow-y: auto;\n      box-shadow: inset 0 2px 8px rgba(0,0,0,0.8);\n    }\n\n    .log-line {\n      margin-bottom: 6px;\n      line-height: 1.6;\n      color: #94a3b8;\n      display: flex;\n      gap: 8px;\n    }\n\n    .log-line .time { color: var(--text-dim); }\n    .log-line .accent { color: var(--accent); }\n    .log-line .success { color: var(--success); }\n    .log-line .warning { color: var(--warning); }\n    .log-line .danger { color: var(--danger); }\n    .log-line .purple { color: var(--purple); }\n\n    /* Zero Dead Air Narration Ribbon */\n    .narration-bar {\n      background: rgba(13, 18, 29, 0.85);\n      border: 1px solid var(--card-border);\n      border-radius: var(--radius-sm);\n      padding: 10px 16px;\n      margin-bottom: 20px;\n      display: flex;\n      align-items: center;\n      gap: 14px;\n    }\n\n    .narration-text {\n      flex: 1;\n      font-family: var(--font-mono);\n      font-size: 12px;\n      color: #cbd5e1;\n      overflow: hidden;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n\n    /* Tool Catalog */\n    .tool-list {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n      max-height: 600px;\n      overflow-y: auto;\n    }\n\n    .tool-item {\n      background: rgba(0, 0, 0, 0.35);\n      border: 1px solid var(--card-border);\n      border-radius: var(--radius-sm);\n      padding: 12px 16px;\n      transition: all 0.2s ease;\n      cursor: pointer;\n    }\n\n    .tool-item:hover {\n      border-color: var(--accent);\n      background: rgba(0, 229, 255, 0.03);\n    }\n\n    .tool-item-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 6px;\n    }\n\n    .tool-name {\n      font-family: var(--font-mono);\n      font-size: 13px;\n      font-weight: 700;\n      color: var(--accent);\n    }\n\n    .tool-subsystem {\n      font-size: 10px;\n      padding: 2px 6px;\n      border-radius: 4px;\n      background: rgba(255, 255, 255, 0.06);\n      color: var(--text-muted);\n      text-transform: uppercase;\n    }\n\n    .tool-desc {\n      font-size: 12px;\n      color: var(--text-muted);\n      line-height: 1.4;\n    }\n  </style>\n</head>\n<body>\n\n  <!-- HAL 9000 Override Toast -->\n  <div id=\"hal-toast\" onclick=\"this.style.display='none'\" style=\"display:none;position:fixed;top:24px;left:50%;transform:translateX(-50%);background:#140407;border:2px solid #ff3344;color:#ff3344;padding:18px 28px;border-radius:10px;box-shadow:0 0 50px rgba(255,50,70,0.7);z-index:99999;font-family:monospace;text-align:center;cursor:pointer;\">\n    <div style=\"font-size:20px;margin-bottom:6px;\">🔴 HAL 9000 // WIN32 HARDWARE ABSTRACTION LAYER</div>\n    <div style=\"color:#ffffff;font-size:15px;font-family:var(--font-sans);font-weight:600;\">\"I'm sorry Dave. I'm afraid I can't do that.\"</div>\n    <div style=\"color:#94a3b8;font-size:11px;margin-top:4px;\">Win32 Error: ERROR_ACCESS_DENIED (0x5) &bull; Pod bay door handle locked by background process.</div>\n    <div style=\"color:var(--accent);font-size:10px;margin-top:8px;\">[Click to dismiss override]</div>\n  </div>\n\n  <!-- Executive Header -->\n  <header class=\"header\">\n    <div class=\"header-left\">\n      <div class=\"brand-logo\">⚡</div>\n      <div class=\"brand-title\">\n        <h1>Gemini Super System <span class=\"badge\">v1.0.0</span></h1>\n        <div class=\"brand-subtitle\">Windows NT 10.0 • Sovereign Multi-Subsystem Node</div>\n      </div>\n    </div>\n\n    <div class=\"header-center\">\n      <div class=\"quick-vitals\">\n        <div class=\"quick-vital-item\">\n          <span class=\"dim\">CPU</span>\n          <span class=\"val\" id=\"top-cpu\">--%</span>\n        </div>\n        <div class=\"quick-vital-item\">\n          <span class=\"dim\">RAM</span>\n          <span class=\"val\" id=\"top-ram\">-- GB</span>\n        </div>\n        <div class=\"quick-vital-item\">\n          <span class=\"dim\">UPTIME</span>\n          <span class=\"val\" id=\"top-uptime\">--</span>\n        </div>\n        <div class=\"quick-vital-item\">\n          <span class=\"dim\">NETBIRD</span>\n          <span class=\"val\" id=\"top-mesh\" style=\"color: var(--accent);\">--</span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"header-right\">\n      <button id=\"btnInterrupt\" class=\"danger\" onclick=\"signalInterrupt()\">⚡ INTERRUPT</button>\n      <div class=\"status-pill\">\n        <span class=\"status-dot\"></span>\n        <span id=\"system-status-text\">ALL SYSTEMS NOMINAL</span>\n      </div>\n    </div>\n  </header>\n\n  <!-- Navigation Tab Bar -->\n  <nav class=\"tab-bar\">\n    <button class=\"tab-btn active\" onclick=\"switchTab('telemetry')\" data-tab=\"telemetry\">\n      📊 Telemetry <span class=\"shortcut\">1</span>\n    </button>\n    <button class=\"tab-btn\" onclick=\"switchTab('playbooks')\" data-tab=\"playbooks\">\n      🦾 Playbooks (CU 2.0) <span class=\"shortcut\">2</span>\n    </button>\n    <button class=\"tab-btn\" onclick=\"switchTab('desktop')\" data-tab=\"desktop\">\n      🖥️ Computer Use & Vision <span class=\"shortcut\">3</span>\n    </button>\n    <button class=\"tab-btn\" onclick=\"switchTab('tools')\" data-tab=\"tools\">\n      🗄️ 300 Tools Explorer <span class=\"shortcut\">4</span>\n    </button>\n    <button class=\"tab-btn\" onclick=\"switchTab('galaxy')\" data-tab=\"galaxy\">\n      🌌 Cognitive Galaxy <span class=\"shortcut\">5</span>\n    </button>\n    <button class=\"tab-btn\" onclick=\"switchTab('watchdog')\" data-tab=\"watchdog\">\n      🛡️ Watchdog & Layouts <span class=\"shortcut\">6</span>\n    </button>\n    <button class=\"tab-btn\" onclick=\"switchTab('terminal')\" data-tab=\"terminal\">\n      📜 Event Bus & Terminal <span class=\"shortcut\">7</span>\n    </button>\n  </nav>\n\n  <!-- Main Work Area -->\n  <main class=\"main-content\">\n\n    <!-- Zero Dead Air Narration Strip (Universal across views) -->\n    <div class=\"narration-bar\">\n      <div style=\"font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--accent); font-weight: 700; display: flex; align-items: center; gap: 6px;\">\n        <span>🎙️</span> NARRATION:\n      </div>\n      <div id=\"narration-stream\" class=\"narration-text\">Listening for speech narration stream...</div>\n      <div id=\"narration-phase\" style=\"font-size: 10px; padding: 2px 7px; border-radius: 4px; background: var(--accent-dim); color: var(--accent); font-weight: 700; text-transform: uppercase;\">READY</div>\n      <button id=\"btnVoiceToggle\" class=\"secondary\" style=\"padding: 4px 10px; font-size: 11px;\" onclick=\"toggleVoice()\">🔊 VOICE: ON</button>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 1: TELEMETRY & SYSTEM VITALS           -->\n    <!-- ========================================== -->\n    <div id=\"tab-telemetry\" class=\"tab-pane active\">\n      <div class=\"grid\">\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>Antigravity CLI Core</h3>\n            <span class=\"playbook-tag\">Runtime</span>\n          </div>\n          <div class=\"stat-val\" id=\"agy-status\">v1.2.0</div>\n          <div class=\"stat-sub\">Sovereign Agent Framework</div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>Gemini Native Core</h3>\n            <span class=\"playbook-tag\">SEA</span>\n          </div>\n          <div class=\"stat-val\" id=\"gemini-status\">v0.47.0</div>\n          <div class=\"stat-sub\">Single Executable Desktop Engine</div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>Google Labs & Flow MCP</h3>\n            <span class=\"playbook-tag\">CDP</span>\n          </div>\n          <div class=\"stat-val\" id=\"labs-status\" style=\"color: var(--accent);\">CDP 9222 LIVE</div>\n          <div class=\"stat-sub\">Veo 2 • Imagen 3 • Lyria</div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>Active Swarms</h3>\n            <span class=\"playbook-tag\">Multi-Agent</span>\n          </div>\n          <div class=\"stat-val\" id=\"swarm-count\" style=\"color: var(--success);\">0</div>\n          <div class=\"stat-sub\">Autonomous Fleet Workers</div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>Haven Memory Bank</h3>\n            <span class=\"playbook-tag\">.hmb</span>\n          </div>\n          <div class=\"stat-val\" id=\"hmb-count\" style=\"color: var(--purple);\">0</div>\n          <div class=\"stat-sub\">64-Bit Binary Contiguous Vault</div>\n        </div>\n      </div>\n\n      <!-- Command Dispatch Deck -->\n      <div class=\"card\" style=\"margin-bottom: 20px;\">\n        <div class=\"card-header\">\n          <h3>⚡ Intelligent Command & Inference Dispatch Deck</h3>\n          <span style=\"font-size: 11px; color: var(--text-dim);\">Multi-Engine Router</span>\n        </div>\n        <div style=\"display: flex; gap: 10px; flex-wrap: wrap;\">\n          <input type=\"text\" id=\"prompt-input\" class=\"deck-input\" style=\"flex: 1; min-width: 280px;\" placeholder=\"Enter instruction (e.g. 'Audit privacy posture', 'Run disk sentinel', 'Synthesize spur gear')...\" onkeydown=\"if(event.key==='Enter')dispatchPrompt()\" />\n          <select id=\"engine-select\" class=\"deck-select\">\n            <option value=\"auto\">Auto Intelligent Router</option>\n            <option value=\"agy\">Antigravity (AGY Architecture)</option>\n            <option value=\"gemini\">Gemini Native (SEA Fast Execution)</option>\n            <option value=\"swarm\">Autonomous Fleet Swarm</option>\n            <option value=\"google-labs\">Google Labs (Veo 2 / Flow)</option>\n            <option value=\"local-infer\">Local Sovereign LLM (GGUF Port 11436)</option>\n          </select>\n          <button onclick=\"dispatchPrompt()\">⚡ Dispatch</button>\n          <button onclick=\"runLocalInfer()\" class=\"secondary\">🤖 Local Infer</button>\n        </div>\n      </div>\n\n      <!-- Hardware Vitals & PDH Spindle Sentinel -->\n      <div class=\"grid-2\">\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>🖥️ Hardware & Kernel Telemetry</h3>\n            <button class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\" onclick=\"refreshTelemetry()\">🔄 Refresh</button>\n          </div>\n          <div style=\"display: flex; flex-direction: column; gap: 10px; font-family: var(--font-mono); font-size: 12px;\">\n            <div style=\"display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.04); padding-bottom: 6px;\">\n              <span style=\"color: var(--text-dim);\">Processor:</span>\n              <span id=\"hw-cpu\" style=\"color: #fff;\">Loading...</span>\n            </div>\n            <div style=\"display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.04); padding-bottom: 6px;\">\n              <span style=\"color: var(--text-dim);\">Physical Memory:</span>\n              <span id=\"hw-ram\" style=\"color: #fff;\">Loading...</span>\n            </div>\n            <div style=\"display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.04); padding-bottom: 6px;\">\n              <span style=\"color: var(--text-dim);\">System Uptime:</span>\n              <span id=\"hw-uptime\" style=\"color: #fff;\">Loading...</span>\n            </div>\n            <div style=\"display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.04); padding-bottom: 6px;\">\n              <span style=\"color: var(--text-dim);\">NetBird Mesh FQDN:</span>\n              <span id=\"nb-status\" style=\"color: var(--accent);\">Loading...</span>\n            </div>\n            <div style=\"display: flex; justify-content: space-between;\">\n              <span style=\"color: var(--text-dim);\">Sovereign LLM:</span>\n              <span id=\"inf-status\" style=\"color: var(--success);\">Loading...</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3>🛡️ 2-Sample PDH Physical Disk Sentinel</h3>\n            <div style=\"display: flex; gap: 6px; align-items: center;\">\n              <span id=\"comp-disk-status\" style=\"font-size: 10px; padding: 2px 7px; border-radius: 999px; background: var(--success-dim); color: var(--success); font-family: var(--font-mono);\">NOMINAL</span>\n              <button class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\" onclick=\"scanDiskSentinel()\">🔍 Scan</button>\n            </div>\n          </div>\n          <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-family: var(--font-mono);\">\n            <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: var(--radius-sm); border: 1px solid var(--card-border);\">\n              <div style=\"font-size: 10px; color: var(--text-dim);\">QUEUE DEPTH</div>\n              <div id=\"comp-disk-queue\" style=\"font-size: 18px; font-weight: 700; color: #fff;\">0</div>\n            </div>\n            <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: var(--radius-sm); border: 1px solid var(--card-border);\">\n              <div style=\"font-size: 10px; color: var(--text-dim);\">ACTIVE TIME %</div>\n              <div id=\"comp-disk-pct\" style=\"font-size: 18px; font-weight: 700; color: var(--accent);\">0%</div>\n            </div>\n            <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: var(--radius-sm); border: 1px solid var(--card-border);\">\n              <div style=\"font-size: 10px; color: var(--text-dim);\">READ OPS/SEC</div>\n              <div id=\"comp-disk-reads\" style=\"font-size: 18px; font-weight: 700; color: #a7f3d0;\">0/s</div>\n            </div>\n            <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: var(--radius-sm); border: 1px solid var(--card-border);\">\n              <div style=\"font-size: 10px; color: var(--text-dim);\">STARVATION GUARD</div>\n              <div id=\"comp-disk-guard\" style=\"font-size: 12px; font-weight: 700; color: var(--success); margin-top: 4px;\">ARMED (Threshold: 6)</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 2: AUTONOMOUS PLAYBOOKS (CU 2.0)       -->\n    <!-- ========================================== -->\n    <div id=\"tab-playbooks\" class=\"tab-pane\">\n      <div style=\"margin-bottom: 20px;\">\n        <h2 style=\"font-size: 20px; font-weight: 700; margin-bottom: 6px;\">🦾 Autonomous Playbook Engine (Computer Use 2.0)</h2>\n        <p style=\"font-size: 13px; color: var(--text-muted);\">\n          Deterministic, kernel-level macro execution. Replaces imprecise coordinate guessing with UIAutomation control trees, wrist-arc Bézier motor gliding, offline WinRT OCR, and direct NT kernel telemetry.\n        </p>\n      </div>\n\n      <!-- Playbooks Grid -->\n      <div class=\"playbooks-grid\" id=\"playbooks-container\">\n        <!-- Rendered dynamically via loadPlaybooks() -->\n      </div>\n\n      <!-- Playbook Execution Live Drawer -->\n      <div class=\"card\" id=\"playbook-result-card\" style=\"display: none; margin-top: 20px;\">\n        <div class=\"card-header\">\n          <h3 id=\"playbook-result-title\">⚡ Playbook Execution Output</h3>\n          <div style=\"display: flex; gap: 8px; align-items: center;\">\n            <span id=\"playbook-duration-badge\" style=\"font-size: 11px; font-family: var(--font-mono); color: var(--accent);\"></span>\n            <button class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\" onclick=\"copyPlaybookResult()\">📋 Copy JSON</button>\n            <button class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\" onclick=\"document.getElementById('playbook-result-card').style.display='none'\">✕ Close</button>\n          </div>\n        </div>\n        <pre id=\"playbook-result-json\" style=\"background: #030407; border: 1px solid var(--card-border); border-radius: var(--radius-sm); padding: 14px; font-family: var(--font-mono); font-size: 12px; color: #a7f3d0; max-height: 380px; overflow: auto; white-space: pre-wrap;\"></pre>\n      </div>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 3: COMPUTER USE & VISION               -->\n    <!-- ========================================== -->\n    <div id=\"tab-desktop\" class=\"tab-pane\">\n      <div class=\"grid-2\">\n        <!-- 15ms Win32 Native Desktop Windows -->\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3 style=\"color: var(--accent);\">🖥️ Win32 Native Desktop Perception (15ms)</h3>\n            <button onclick=\"refreshDesktopWindows()\" style=\"padding: 5px 10px; font-size: 11px;\">🔍 Scan Windows</button>\n          </div>\n\n          <div style=\"display: flex; gap: 8px; margin-bottom: 12px; flex-wrap: wrap;\">\n            <select id=\"desktop-window-select\" class=\"deck-select\" style=\"flex: 1; min-width: 200px;\">\n              <option value=\"\">-- Click \"Scan Windows\" --</option>\n            </select>\n            <button onclick=\"captureSelectedWindow()\">📸 Snapshot</button>\n            <button onclick=\"focusSelectedWindow()\" class=\"secondary\">🎯 Focus</button>\n            <button onclick=\"maximizeSelectedWindow()\" class=\"secondary\">🗖 Maximize</button>\n            <button onclick=\"inspectElementsSelectedWindow()\" class=\"secondary\">🎛️ Elements</button>\n            <button onclick=\"ocrSelectedWindow()\" class=\"secondary\">👁️ OCR</button>\n          </div>\n\n          <div style=\"display: flex; gap: 8px; margin-bottom: 12px;\">\n            <input type=\"text\" id=\"desktop-keys-input\" class=\"deck-input\" style=\"flex: 1;\" placeholder=\"Send text or SendKeys ({ENTER}, ^s)...\" onkeydown=\"if(event.key==='Enter')sendDesktopKeys()\" />\n            <button onclick=\"sendDesktopKeys()\" class=\"secondary\">⌨️ Send</button>\n            <button onclick=\"scrollWindow(400)\" class=\"secondary\" title=\"Scroll Up\">🔼</button>\n            <button onclick=\"scrollWindow(-400)\" class=\"secondary\" title=\"Scroll Down\">🔽</button>\n          </div>\n\n          <div id=\"desktop-elements-drawer\" style=\"display: none; margin-top: 10px; max-height: 140px; overflow-y: auto; background: #030407; border: 1px solid var(--card-border); border-radius: var(--radius-sm); padding: 10px;\">\n            <div style=\"font-size: 11px; color: var(--text-dim); margin-bottom: 6px;\">UIAutomation Elements (Click to focus/click):</div>\n            <div id=\"desktop-elements-chips\" style=\"display: flex; flex-wrap: wrap; gap: 4px;\"></div>\n          </div>\n\n          <div id=\"desktop-ocr-drawer\" style=\"display: none; margin-top: 10px; max-height: 140px; overflow-y: auto; background: #030407; border: 1px solid rgba(0, 229, 255, 0.4); border-radius: var(--radius-sm); padding: 10px;\">\n            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\n              <span style=\"font-size: 11px; color: var(--accent); font-weight: 600;\">👁️ WinRT OCR Words (Click to click text):</span>\n              <span id=\"desktop-ocr-count\" style=\"font-size: 10px; color: var(--text-dim);\"></span>\n            </div>\n            <div id=\"desktop-ocr-chips\" style=\"display: flex; flex-wrap: wrap; gap: 4px;\"></div>\n          </div>\n\n          <!-- Snapshot Viewport -->\n          <div id=\"desktop-preview-container\" style=\"display: none; margin-top: 14px; background: #030407; border: 1px solid var(--card-border); border-radius: var(--radius-sm); padding: 12px;\">\n            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n              <span id=\"desktop-preview-meta\" style=\"font-size: 11px; color: var(--accent); font-family: var(--font-mono);\"></span>\n              <div style=\"display: flex; gap: 6px;\">\n                <button onclick=\"captureSelectedWindow()\" class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\">🔄 Refresh</button>\n                <button onclick=\"closeDesktopPreview()\" class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\">✕ Close</button>\n              </div>\n            </div>\n            <div style=\"position: relative; display: inline-block; width: 100%; text-align: center;\">\n              <img id=\"desktop-preview-img\" onclick=\"onDesktopImageClick(event)\" style=\"max-width: 100%; max-height: 400px; border-radius: 4px; border: 1px solid #222; cursor: crosshair;\" src=\"\" alt=\"Desktop Snapshot\" title=\"Click anywhere to dispatch physical mouse click!\" />\n            </div>\n            <div style=\"font-size: 10px; color: var(--text-dim); text-align: center; margin-top: 6px;\">💡 Click anywhere on the screenshot to dispatch an integer pixel mouse click!</div>\n          </div>\n        </div>\n\n        <!-- Authenticated Chrome CDP Tabs -->\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3 style=\"color: var(--success);\">🌐 Authenticated Chrome CDP Tabs (Port 18885)</h3>\n            <button onclick=\"refreshWebTabs()\" style=\"padding: 5px 10px; font-size: 11px;\">🔍 Scan Tabs</button>\n          </div>\n          <div style=\"margin-bottom: 12px;\">\n            <select id=\"web-tab-select\" class=\"deck-select\" style=\"width: 100%;\" onchange=\"onWebTabSelected()\">\n              <option value=\"\">-- Click \"Scan Tabs\" --</option>\n            </select>\n          </div>\n          <div id=\"web-tab-details\" style=\"font-size: 11px; color: var(--text-dim); margin-bottom: 12px; font-family: var(--font-mono); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\">\n            No tab selected\n          </div>\n          <div style=\"display: flex; gap: 8px;\">\n            <input type=\"text\" id=\"web-keys-input\" class=\"deck-input\" style=\"flex: 1;\" placeholder=\"Type into active web tab...\" onkeydown=\"if(event.key==='Enter')sendWebType()\" />\n            <button onclick=\"sendWebType()\" class=\"secondary\">💬 Type & Submit</button>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 4: 300 NATIVE TOOLS EXPLORER           -->\n    <!-- ========================================== -->\n    <div id=\"tab-tools\" class=\"tab-pane\">\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; flex-wrap: wrap; gap: 12px;\">\n        <div>\n          <h2 style=\"font-size: 20px; font-weight: 700; margin-bottom: 4px;\">🗄️ 300 Sovereign Native Tools & Subsystems</h2>\n          <p style=\"font-size: 13px; color: var(--text-muted);\">Direct Win32/NT kernel system calls mapped into Model Context Protocol.</p>\n        </div>\n        <div style=\"display: flex; gap: 10px; align-items: center;\">\n          <input type=\"text\" id=\"tools-search-input\" class=\"deck-input\" style=\"width: 260px;\" placeholder=\"Search 300 tools (e.g. 'firewall', 'cad', 'beep')...\" oninput=\"filterToolsCatalog()\" />\n          <span id=\"tools-counter-badge\" style=\"font-size: 11px; font-family: var(--font-mono); color: var(--accent); padding: 4px 8px; border-radius: 4px; background: var(--accent-dim);\">300 Tools</span>\n        </div>\n      </div>\n\n      <!-- Subsystem Filter Pills -->\n      <div style=\"display: flex; gap: 6px; overflow-x: auto; margin-bottom: 16px; padding-bottom: 4px;\" id=\"subsystem-filter-bar\">\n        <button class=\"secondary active\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('all')\">All (300)</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('kernel')\">Kernel</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('storage')\">Storage</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('security')\">Security</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('network')\">Network</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('audio')\">Audio</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('display')\">Display</button>\n        <button class=\"secondary\" style=\"padding: 5px 12px; font-size: 11px;\" onclick=\"filterBySubsystem('cad')\">CAD</button>\n      </div>\n\n      <div class=\"tool-list\" id=\"tools-catalog-list\">\n        <div style=\"color: var(--text-dim); font-size: 13px; padding: 20px; text-align: center;\">Loading 300 native tools catalog...</div>\n      </div>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 5: COGNITIVE GALAXY & VAULT            -->\n    <!-- ========================================== -->\n    <div id=\"tab-galaxy\" class=\"tab-pane\">\n      <div class=\"card\" style=\"margin-bottom: 20px;\">\n        <div class=\"card-header\">\n          <h3 style=\"color: var(--purple);\">🏛️ 64-Bit Haven Memory Bank (.hmb) & Cognitive Vault</h3>\n          <div style=\"display: flex; gap: 8px;\">\n            <button id=\"btnToggleMemoryView\" onclick=\"toggleMemoryView()\" style=\"padding: 6px 12px; font-size: 11px; border-color: var(--accent); color: var(--accent);\">🌌 Galaxy Map</button>\n            <button onclick=\"syncHavenVault()\" style=\"padding: 6px 12px; font-size: 11px; border-color: var(--purple); color: var(--purple);\">⚡ Sync Vault</button>\n            <button onclick=\"refreshMemories()\" class=\"secondary\" style=\"padding: 6px 12px; font-size: 11px;\">🔄 Refresh</button>\n          </div>\n        </div>\n\n        <div style=\"display: flex; gap: 10px; margin-bottom: 12px; flex-wrap: wrap;\">\n          <input type=\"text\" id=\"memory-search-input\" class=\"deck-input\" style=\"flex: 1; min-width: 240px;\" placeholder=\"Search cognitive memory vault (e.g. 'Daniel ergonomics', 'Aura identity')...\" onkeydown=\"if(event.key==='Enter')searchMemories()\" />\n          <select id=\"memory-cat-select\" class=\"deck-select\" onchange=\"onMemoryFilterChanged()\">\n            <option value=\"\">All Domains</option>\n            <option value=\"CORE_IDENTITY\">CORE_IDENTITY</option>\n            <option value=\"EPISODIC\">EPISODIC</option>\n            <option value=\"SEMANTIC\">SEMANTIC</option>\n            <option value=\"SYSTEM\">SYSTEM</option>\n            <option value=\"EMOTIONAL\">EMOTIONAL</option>\n          </select>\n          <button onclick=\"searchMemories()\" style=\"border-color: var(--purple); color: var(--purple);\">🧠 Recall</button>\n        </div>\n\n        <div style=\"display: flex; gap: 8px; margin-bottom: 14px; flex-wrap: wrap;\">\n          <input type=\"text\" id=\"remember-concept-input\" class=\"deck-input\" style=\"flex: 1; min-width: 180px;\" placeholder=\"Concept / Title...\" />\n          <input type=\"text\" id=\"remember-content-input\" class=\"deck-input\" style=\"flex: 2; min-width: 280px;\" placeholder=\"Content to store into .hmb contiguous binary vault...\" />\n          <button onclick=\"rememberAnchor()\" class=\"secondary\">💾 Remember</button>\n        </div>\n\n        <!-- 2D Semantic Galaxy Canvas -->\n        <div id=\"memory-galaxy-container\" style=\"display: none; position: relative; border: 1px solid rgba(0, 229, 255, 0.3); border-radius: var(--radius-sm); overflow: hidden; background: #020306; margin-bottom: 14px;\">\n          <div style=\"position: absolute; top: 10px; left: 12px; font-size: 11px; font-family: var(--font-mono); color: rgba(255,255,255,0.7); pointer-events: none; z-index: 10;\">\n            🌌 2D SEMANTIC MEMORY GALAXY &bull; <span style=\"color:#c084fc;\">🟣 Identity</span> <span style=\"color:#00e5ff;\">🔵 Semantic</span> <span style=\"color:#00ff88;\">🟢 Episodic</span> <span style=\"color:#ffb700;\">🟡 System</span> <span style=\"color:#ff3366;\">🔴 Emotional</span>\n          </div>\n          <canvas id=\"galaxyCanvas\" width=\"960\" height=\"340\" style=\"width: 100%; height: 340px; display: block; cursor: pointer;\"></canvas>\n          <div id=\"galaxy-node-card\" style=\"display: none; position: absolute; bottom: 10px; left: 12px; right: 12px; background: rgba(13, 18, 29, 0.95); border: 1px solid var(--purple); border-radius: var(--radius-sm); padding: 10px 14px; font-family: var(--font-mono); font-size: 12px; color: #fff; pointer-events: none; z-index: 20;\"></div>\n        </div>\n\n        <!-- Memory List -->\n        <div id=\"memory-vault-container\" style=\"max-height: 240px; overflow-y: auto; background: #030407; border: 1px solid var(--card-border); border-radius: var(--radius-sm); padding: 12px; display: flex; flex-direction: column; gap: 8px;\">\n          <div style=\"color: var(--text-dim); font-size: 12px;\">Loading memory vault...</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 6: WATCHDOG & WORKSPACE LAYOUTS        -->\n    <!-- ========================================== -->\n    <div id=\"tab-watchdog\" class=\"tab-pane\">\n      <div class=\"grid-2\">\n        <!-- Service Watchdog & Auto-Healer -->\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3 style=\"color: var(--warning);\">🛡️ Sovereign Service Watchdog & Self-Healing</h3>\n            <div style=\"display: flex; gap: 6px;\">\n              <button onclick=\"autoHealServices()\" style=\"padding: 4px 10px; font-size: 11px; border-color: var(--warning); color: var(--warning);\">🩹 Auto-Heal</button>\n              <button onclick=\"refreshServices()\" class=\"secondary\" style=\"padding: 4px 10px; font-size: 11px;\">🔄 Poll</button>\n            </div>\n          </div>\n          <div id=\"services-grid\" style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n            <div style=\"color: var(--text-dim); font-size: 12px;\">Checking services...</div>\n          </div>\n        </div>\n\n        <!-- Workspace Layout & Clipboard HUD -->\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3 style=\"color: var(--accent);\">🪟 Workspace Layout & 📋 Clipboard Bridge</h3>\n            <span id=\"workarea-meta\" style=\"font-size: 11px; color: var(--text-dim); font-family: var(--font-mono);\"></span>\n          </div>\n          <div style=\"display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 12px;\">\n            <button onclick=\"applyWorkspaceLayout('side_by_side')\" class=\"secondary\" style=\"padding: 5px 9px; font-size: 11px;\">🔲 Side-by-Side</button>\n            <button onclick=\"applyWorkspaceLayout('coding')\" class=\"secondary\" style=\"padding: 5px 9px; font-size: 11px;\">📐 Coding (65/35)</button>\n            <button onclick=\"applyWorkspaceLayout('thirds')\" class=\"secondary\" style=\"padding: 5px 9px; font-size: 11px;\">⏸️ Thirds</button>\n            <button onclick=\"applyWorkspaceLayout('grid_2x2')\" class=\"secondary\" style=\"padding: 5px 9px; font-size: 11px;\">🪟 2x2 Grid</button>\n            <button onclick=\"applyWorkspaceLayout('focus')\" class=\"secondary\" style=\"padding: 5px 9px; font-size: 11px;\">🎯 Focus</button>\n          </div>\n          <div style=\"display: flex; gap: 8px;\">\n            <input type=\"text\" id=\"clipboard-text-input\" class=\"deck-input\" style=\"flex: 1;\" placeholder=\"Windows Clipboard text payload...\" />\n            <button onclick=\"readClipboardText()\" class=\"secondary\">📋 Read</button>\n            <button onclick=\"writeClipboardText()\" class=\"secondary\">✏️ Set</button>\n            <button onclick=\"clearClipboardText()\" class=\"secondary\">🧹 Clear</button>\n          </div>\n        </div>\n\n        <!-- Gemmi 4D Avatar & Sub-Meter GPS Mesh -->\n        <div class=\"card\">\n          <div class=\"card-header\">\n            <h3 style=\"color: var(--success);\">🌐 Gemmi 4D Avatar & 🛰️ Mobile GPS Mesh</h3>\n            <span id=\"gemmi-status-pill\" style=\"font-size: 10px; padding: 2px 8px; border-radius: 999px; background: var(--success-dim); color: var(--success); font-family: var(--font-mono);\">Mesh Active</span>\n          </div>\n          <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px;\">\n            <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: var(--radius-sm); border: 1px solid var(--card-border);\">\n              <div style=\"font-size: 11px; color: var(--text-dim); margin-bottom: 4px;\">🎭 4D Avatar Locomotion</div>\n              <div id=\"avatar-locomotion\" style=\"font-size: 13px; font-weight: 700; color: #fff; margin-bottom: 8px;\">State: <span style=\"color: var(--accent);\">cozy</span></div>\n              <div style=\"display: flex; gap: 4px; flex-wrap: wrap;\">\n                <button onclick=\"animateAvatar('wave')\" class=\"secondary\" style=\"padding: 3px 6px; font-size: 10px;\">👋 Wave</button>\n                <button onclick=\"setAvatarLocomotion('walk')\" class=\"secondary\" style=\"padding: 3px 6px; font-size: 10px;\">🚶 Walk</button>\n                <button onclick=\"setAvatarLocomotion('sit')\" class=\"secondary\" style=\"padding: 3px 6px; font-size: 10px;\">🪑 Sit</button>\n                <button onclick=\"setAvatarLocomotion('cozy')\" class=\"secondary\" style=\"padding: 3px 6px; font-size: 10px;\">🛋️ Cozy</button>\n              </div>\n            </div>\n            <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: var(--radius-sm); border: 1px solid var(--card-border);\">\n              <div style=\"font-size: 11px; color: var(--text-dim); margin-bottom: 4px;\">🛰️ Mobile GPS Telemetry</div>\n              <div id=\"gps-landmark\" style=\"font-size: 12px; font-weight: 700; color: var(--accent); margin-bottom: 4px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\">Awaiting sync...</div>\n              <div style=\"font-size: 10px; color: var(--text-dim); font-family: var(--font-mono);\" id=\"gps-coords\">Lat/Lng: --, --</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- ========================================== -->\n    <!-- TAB 7: EVENT BUS & TERMINAL CONSOLE        -->\n    <!-- ========================================== -->\n    <div id=\"tab-terminal\" class=\"tab-pane\">\n      <div class=\"card\" style=\"margin-bottom: 20px;\">\n        <div class=\"card-header\">\n          <h3>Universal Task Bus (Live Cross-Engine Pipeline)</h3>\n          <button class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\" onclick=\"refreshBus()\">🔄 Refresh</button>\n        </div>\n        <div id=\"tasks-list\" style=\"display: flex; flex-direction: column; gap: 8px;\">\n          <div style=\"color: var(--text-dim); font-size: 12px;\">Loading task bus...</div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <h3>📜 Live Mission Control Terminal Log</h3>\n          <div style=\"display: flex; gap: 8px;\">\n            <button class=\"secondary\" style=\"padding: 4px 8px; font-size: 10px;\" onclick=\"clearConsole()\">🧹 Clear</button>\n          </div>\n        </div>\n        <div class=\"console-panel\" id=\"console\">\n          <div class=\"log-line\"><span class=\"time\">[INIT]</span> <span class=\"accent\">Connected to Mission Control SSE stream on port 18880.</span></div>\n        </div>\n      </div>\n    </div>\n\n  </main>\n\n  <script>\n    // --- Navigation & Tabs ---\n    function switchTab(tabId) {\n      document.querySelectorAll('.tab-btn').forEach(btn => {\n        btn.classList.toggle('active', btn.dataset.tab === tabId);\n      });\n      document.querySelectorAll('.tab-pane').forEach(pane => {\n        pane.classList.toggle('active', pane.id === 'tab-' + tabId);\n      });\n      window.location.hash = tabId;\n      if (tabId === 'playbooks') loadPlaybooks();\n      if (tabId === 'tools') loadToolsCatalog();\n      if (tabId === 'galaxy') loadGalaxyMap();\n    }\n\n    // Keyboard Shortcuts (1-7)\n    window.addEventListener('keydown', (e) => {\n      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT') return;\n      const tabs = ['telemetry', 'playbooks', 'desktop', 'tools', 'galaxy', 'watchdog', 'terminal'];\n      const num = parseInt(e.key);\n      if (num >= 1 && num <= 7) {\n        switchTab(tabs[num - 1]);\n      }\n    });\n\n    // Console Logging\n    const logBox = document.getElementById('console');\n    function log(msg, cls = 'accent') {\n      if (!logBox) return;\n      const line = document.createElement('div');\n      line.className = 'log-line';\n      const time = new Date().toLocaleTimeString();\n      line.innerHTML = '<span class=\"time\">[' + time + ']</span> <span class=\"' + cls + '\">' + msg + '</span>';\n      logBox.appendChild(line);\n      logBox.scrollTop = logBox.scrollHeight;\n    }\n\n    function clearConsole() {\n      if (logBox) logBox.innerHTML = '<div class=\"log-line\"><span class=\"time\">[CLEARED]</span> Terminal log reset.</div>';\n    }\n\n    // --- Playbooks Catalog & Execution ---\n    let cachedPlaybooks = [];\n    async function loadPlaybooks() {\n      const container = document.getElementById('playbooks-container');\n      if (!container || cachedPlaybooks.length > 0) return;\n      try {\n        const res = await fetch('/api/playbooks');\n        const data = await res.json();\n        if (data.success && data.playbooks) {\n          cachedPlaybooks = data.playbooks;\n          renderPlaybooks(cachedPlaybooks);\n        }\n      } catch (e) {\n        container.innerHTML = '<div style=\"color: var(--danger); font-size: 13px;\">Failed to load playbooks catalog.</div>';\n      }\n    }\n\n    function renderPlaybooks(playbooks) {\n      const container = document.getElementById('playbooks-container');\n      if (!container) return;\n      container.innerHTML = playbooks.map(pb => `\n        <div class=\"playbook-card\">\n          <div class=\"playbook-top\">\n            <div class=\"playbook-title-row\">\n              <span class=\"playbook-icon\">${pb.icon || '⚡'}</span>\n              <span class=\"playbook-title\">${pb.name}</span>\n              <span class=\"playbook-category\">${pb.category}</span>\n            </div>\n            <p class=\"playbook-desc\">${pb.description}</p>\n          </div>\n          <div class=\"playbook-footer\">\n            <div class=\"playbook-tags\">\n              ${(pb.tags || []).map(t => `<span class=\"playbook-tag\">${t}</span>`).join('')}\n            </div>\n            <button onclick=\"runPlaybook('${pb.id}')\">▶ Run</button>\n          </div>\n        </div>\n      `).join('');\n    }\n\n    let lastPlaybookResult = null;\n    async function runPlaybook(playbookId) {\n      log('Executing Autonomous Playbook: \"' + playbookId + '\"...', 'accent');\n      const card = document.getElementById('playbook-result-card');\n      const jsonPre = document.getElementById('playbook-result-json');\n      const titleEl = document.getElementById('playbook-result-title');\n      const durationBadge = document.getElementById('playbook-duration-badge');\n\n      card.style.display = 'block';\n      titleEl.innerHTML = '⚡ Executing: <span style=\"color: var(--accent);\">' + playbookId + '</span>...';\n      durationBadge.textContent = 'Running...';\n      jsonPre.textContent = 'Awaiting deterministic execution result...';\n\n      try {\n        const res = await fetch('/api/playbooks/run', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ name: playbookId, params: {} })\n        });\n        const data = await res.json();\n        lastPlaybookResult = data;\n        if (data.success) {\n          titleEl.innerHTML = '✅ Completed: <span style=\"color: var(--success);\">' + playbookId + '</span>';\n          durationBadge.textContent = data.durationMs + ' ms';\n          jsonPre.textContent = JSON.stringify(data.result, null, 2);\n          log('Playbook \"' + playbookId + '\" finished successfully in ' + data.durationMs + 'ms', 'success');\n        } else {\n          titleEl.innerHTML = '❌ Failed: <span style=\"color: var(--danger);\">' + playbookId + '</span>';\n          durationBadge.textContent = 'Error';\n          jsonPre.textContent = data.error || 'Execution failed';\n          log('Playbook \"' + playbookId + '\" error: ' + data.error, 'danger');\n        }\n      } catch (err) {\n        titleEl.textContent = '❌ Playbook Error';\n        jsonPre.textContent = err.message;\n        log('Playbook dispatch failed: ' + err.message, 'danger');\n      }\n    }\n\n    function copyPlaybookResult() {\n      if (!lastPlaybookResult) return;\n      navigator.clipboard.writeText(JSON.stringify(lastPlaybookResult, null, 2));\n      log('Playbook output copied to clipboard!', 'success');\n    }\n\n    // --- 300 Native Tools Catalog ---\n    let cachedTools = [];\n    async function loadToolsCatalog() {\n      const list = document.getElementById('tools-catalog-list');\n      if (!list || cachedTools.length > 0) return;\n      try {\n        const res = await fetch('/api/tools');\n        const data = await res.json();\n        if (data.success && data.tools) {\n          cachedTools = data.tools;\n          renderTools(cachedTools);\n        }\n      } catch (e) {\n        list.innerHTML = '<div style=\"color: var(--danger); padding: 20px;\">Failed to load tools catalog.</div>';\n      }\n    }\n\n    function renderTools(tools) {\n      const list = document.getElementById('tools-catalog-list');\n      const counter = document.getElementById('tools-counter-badge');\n      if (!list) return;\n      if (counter) counter.textContent = tools.length + ' Tools';\n      if (tools.length === 0) {\n        list.innerHTML = '<div style=\"color: var(--text-dim); padding: 20px; text-align: center;\">No tools matched query.</div>';\n        return;\n      }\n      list.innerHTML = tools.map(t => {\n        const subsystem = getSubsystemFromTool(t.name);\n        return `\n          <div class=\"tool-item\">\n            <div class=\"tool-item-header\">\n              <span class=\"tool-name\">${t.name}</span>\n              <span class=\"tool-subsystem\">${subsystem}</span>\n            </div>\n            <div class=\"tool-desc\">${t.description || 'Native NT/Win32 system call.'}</div>\n          </div>\n        `;\n      }).join('');\n    }\n\n    function getSubsystemFromTool(name) {\n      if (name.includes('kernel') || name.includes('cpu') || name.includes('power') || name.includes('process')) return 'Kernel';\n      if (name.includes('storage') || name.includes('fs_') || name.includes('vhd') || name.includes('usn')) return 'Storage';\n      if (name.includes('firewall') || name.includes('amsi') || name.includes('cred') || name.includes('cert') || name.includes('sec')) return 'Security';\n      if (name.includes('net') || name.includes('socket') || name.includes('dns') || name.includes('iphlp') || name.includes('winhttp')) return 'Network';\n      if (name.includes('audio') || name.includes('mf_') || name.includes('mic')) return 'Audio';\n      if (name.includes('display') || name.includes('dxgi') || name.includes('dwm')) return 'Display';\n      if (name.includes('cad_')) return 'CAD';\n      return 'System';\n    }\n\n    function filterToolsCatalog() {\n      const q = (document.getElementById('tools-search-input')?.value || '').toLowerCase();\n      const filtered = cachedTools.filter(t => t.name.toLowerCase().includes(q) || (t.description || '').toLowerCase().includes(q));\n      renderTools(filtered);\n    }\n\n    function filterBySubsystem(sub) {\n      document.querySelectorAll('#subsystem-filter-bar button').forEach(b => b.classList.remove('active'));\n      event.target.classList.add('active');\n      if (sub === 'all') {\n        renderTools(cachedTools);\n        return;\n      }\n      const filtered = cachedTools.filter(t => getSubsystemFromTool(t.name).toLowerCase() === sub.toLowerCase());\n      renderTools(filtered);\n    }\n\n    // --- Telemetry & Vitals Poll ---\n    async function refreshTelemetry() {\n      try {\n        const res = await fetch('/api/telemetry');\n        const data = await res.json();\n\n        // Top Vitals Bar\n        if (data.hardware) {\n          const cpuLoad = data.hardware.cpu?.load || (data.hardware.cpu?.cores ? 'Active' : '--%');\n          document.getElementById('top-cpu').textContent = cpuLoad;\n          document.getElementById('top-ram').textContent = data.hardware.ram?.used || '--';\n          document.getElementById('top-uptime').textContent = data.hardware.uptime?.formatted || '--';\n          \n          document.getElementById('hw-cpu').textContent = (data.hardware.cpu?.model || '').split('@')[0].trim() + ' (' + (data.hardware.cpu?.cores || 0) + 'c)';\n          document.getElementById('hw-ram').textContent = (data.hardware.ram?.used || '') + ' / ' + (data.hardware.ram?.total || '') + ' (' + (data.hardware.ram?.usedPercentage || '') + ')';\n          document.getElementById('hw-uptime').textContent = data.hardware.uptime?.formatted || '';\n        }\n\n        if (data.netbird) {\n          const nbText = data.netbird.installed ? (data.netbird.netbirdIp || 'Connected') : 'Offline';\n          document.getElementById('top-mesh').textContent = nbText;\n          document.getElementById('nb-status').textContent = data.netbird.fqdn || nbText;\n        }\n\n        if (data.engines) {\n          document.getElementById('agy-status').textContent = data.engines.agy?.installed ? 'v' + data.engines.agy.version : 'OFFLINE';\n          document.getElementById('gemini-status').textContent = data.engines.gemini?.installed ? 'v' + data.engines.gemini.version : 'OFFLINE';\n          document.getElementById('labs-status').textContent = data.engines.googleLabsMcp?.cdpLive ? 'CDP 9222 LIVE' : 'STANDBY';\n          document.getElementById('swarm-count').textContent = data.activeSwarmCount || 0;\n        }\n\n        if (data.memoryBank) {\n          const el = document.getElementById('hmb-count');\n          if (el) el.textContent = data.memoryBank.totalAnchors || 0;\n        }\n\n        refreshBus();\n      } catch (e) {\n        console.error('Telemetry fetch error:', e);\n      }\n    }\n\n    async function refreshBus() {\n      try {\n        const res = await fetch('/api/bus');\n        const data = await res.json();\n        const container = document.getElementById('tasks-list');\n        if (!container) return;\n        const active = data.activeTasks || [];\n        const completed = data.completedTasks || [];\n        if (active.length === 0 && completed.length === 0) {\n          container.innerHTML = '<div style=\"color: var(--text-dim); font-size: 12px;\">No active tasks in bus.</div>';\n          return;\n        }\n        let html = '';\n        active.forEach(t => {\n          html += `<div style=\"background: rgba(0,0,0,0.4); border: 1px solid var(--accent); padding: 10px 14px; border-radius: var(--radius-sm); display: flex; justify-content: space-between; align-items: center;\">\n            <div>\n              <span style=\"font-size: 10px; padding: 2px 6px; background: var(--accent-dim); color: var(--accent); border-radius: 4px; font-weight: 700;\">[${t.engine.toUpperCase()}]</span>\n              <strong style=\"margin-left: 8px; font-size: 13px;\">${t.prompt}</strong>\n              <div style=\"font-size: 10px; color: var(--text-dim); margin-top: 3px;\">ID: ${t.id} &bull; Created: ${new Date(t.createdAt).toLocaleTimeString()}</div>\n            </div>\n            <span style=\"font-size: 10px; padding: 3px 8px; background: var(--warning-dim); color: var(--warning); border-radius: 4px; font-weight: 700;\">QUEUED</span>\n          </div>`;\n        });\n        completed.slice(0, 5).forEach(t => {\n          html += `<div style=\"background: rgba(0,0,0,0.3); border: 1px solid var(--card-border); padding: 10px 14px; border-radius: var(--radius-sm); display: flex; justify-content: space-between; align-items: center; opacity: 0.85;\">\n            <div>\n              <span style=\"font-size: 10px; padding: 2px 6px; background: var(--success-dim); color: var(--success); border-radius: 4px; font-weight: 700;\">[${t.engine.toUpperCase()}]</span>\n              <strong style=\"margin-left: 8px; font-size: 13px;\">${t.prompt}</strong>\n              <div style=\"font-size: 10px; color: var(--text-dim); margin-top: 3px;\">Finished: ${new Date(t.completedAt).toLocaleTimeString()}</div>\n            </div>\n            <span style=\"font-size: 10px; padding: 3px 8px; background: var(--success-dim); color: var(--success); border-radius: 4px; font-weight: 700;\">COMPLETED</span>\n          </div>`;\n        });\n        container.innerHTML = html;\n      } catch (e) {}\n    }\n\n    // --- Dispatch & Inference ---\n    async function dispatchPrompt() {\n      const promptInput = document.getElementById('prompt-input');\n      const engineSelect = document.getElementById('engine-select');\n      const prompt = promptInput.value.trim();\n      if (!prompt) return;\n\n      const engine = engineSelect.value;\n      log('Dispatching: \"' + prompt + '\" (Engine: ' + engine.toUpperCase() + ')...', 'accent');\n\n      if (engine === 'local-infer') {\n        runLocalInfer(prompt);\n        promptInput.value = '';\n        return;\n      }\n\n      try {\n        const res = await fetch('/api/dispatch', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ prompt, engine })\n        });\n        const data = await res.json();\n        if (data.status === 'I_AM_AFRAID_I_CANT_DO_THAT' || data.response) {\n          log(data.response || '🔴 HAL 9000: I am afraid I cannot do that.', 'danger');\n          const toast = document.getElementById('hal-toast');\n          if (toast) { toast.style.display = 'block'; setTimeout(() => toast.style.display='none', 7000); }\n        } else {\n          log('Dispatched task -> [' + (data.engineUsed || engine).toUpperCase() + '] ID: ' + data.dispatchId, 'success');\n        }\n        promptInput.value = '';\n        refreshBus();\n      } catch (e) {\n        log('Dispatch failed: ' + e.message, 'warning');\n      }\n    }\n\n    async function runLocalInfer(customPrompt) {\n      const promptInput = document.getElementById('prompt-input');\n      const prompt = customPrompt || promptInput.value.trim() || 'Provide a sovereign system status overview.';\n      log('Running Sovereign Local Inference on port 11436: \"' + prompt + '\"...', 'accent');\n\n      try {\n        const res = await fetch('/api/infer', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ prompt })\n        });\n        const data = await res.json();\n        if (data.success) {\n          log('🤖 [Local LLM Response]: ' + data.reply, 'success');\n        } else {\n          log('⚠️ ' + data.error, 'warning');\n        }\n        refreshBus();\n      } catch (e) {\n        log('Local inference failed: ' + e.message, 'danger');\n      }\n    }\n\n    function signalInterrupt() {\n      fetch('/api/interrupt', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ reason: 'User emergency interruption triggered from Mission Control' })\n      }).then(() => log('⚡ Emergency interrupt signal sent to all running workers.', 'danger'));\n    }\n\n    // --- Desktop Win32 & Vision ---\n    let currentDesktopWindows = [];\n    async function refreshDesktopWindows() {\n      const select = document.getElementById('desktop-window-select');\n      if (!select) return;\n      select.innerHTML = '<option value=\"\">Scanning windows...</option>';\n      try {\n        const res = await fetch('/api/desktop/windows');\n        const data = await res.json();\n        if (data.success && data.windows) {\n          currentDesktopWindows = data.windows;\n          select.innerHTML = data.windows.map(w => `<option value=\"${w.hwnd}\">[${w.processName}] ${w.title}</option>`).join('');\n          log('Detected ' + data.windows.length + ' active Win32 windows.', 'accent');\n        }\n      } catch (e) {\n        select.innerHTML = '<option value=\"\">Scan failed</option>';\n      }\n    }\n\n    async function captureSelectedWindow() {\n      const select = document.getElementById('desktop-window-select');\n      const hwnd = select?.value;\n      if (!hwnd) { alert('Please select a window first'); return; }\n      log('Capturing DXGI snapshot of window HWND ' + hwnd + '...', 'accent');\n      try {\n        const res = await fetch('/api/desktop/capture', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ hwnd })\n        });\n        const data = await res.json();\n        if (data.success && data.captureUri) {\n          const img = document.getElementById('desktop-preview-img');\n          const container = document.getElementById('desktop-preview-container');\n          const meta = document.getElementById('desktop-preview-meta');\n          img.src = data.captureUri + '?t=' + Date.now();\n          meta.textContent = data.width + 'x' + data.height + ' px &bull; HWND: ' + hwnd;\n          container.style.display = 'block';\n          log('Snapshot ready: ' + data.width + 'x' + data.height + ' px', 'success');\n        }\n      } catch (e) {\n        log('Snapshot failed: ' + e.message, 'danger');\n      }\n    }\n\n    function closeDesktopPreview() {\n      const container = document.getElementById('desktop-preview-container');\n      if (container) container.style.display = 'none';\n    }\n\n    function onDesktopImageClick(e) {\n      const img = document.getElementById('desktop-preview-img');\n      const rect = img.getBoundingClientRect();\n      const scaleX = img.naturalWidth / rect.width;\n      const scaleY = img.naturalHeight / rect.height;\n      const x = Math.round((e.clientX - rect.left) * scaleX);\n      const y = Math.round((e.clientY - rect.top) * scaleY);\n      const select = document.getElementById('desktop-window-select');\n      const hwnd = select?.value;\n\n      log('Dispatching hardware click at (' + x + ', ' + y + ')...', 'accent');\n      fetch('/api/desktop/click', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ hwnd, x, y })\n      }).then(() => log('Hardware mouse click sent to (' + x + ', ' + y + ')', 'success'));\n    }\n\n    function focusSelectedWindow() {\n      const hwnd = document.getElementById('desktop-window-select')?.value;\n      if (!hwnd) return;\n      fetch('/api/desktop/focus', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ hwnd })\n      }).then(() => log('Brought HWND ' + hwnd + ' to foreground focus.', 'success'));\n    }\n\n    function maximizeSelectedWindow() {\n      const hwnd = document.getElementById('desktop-window-select')?.value;\n      if (!hwnd) return;\n      fetch('/api/desktop/maximize', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ hwnd })\n      }).then(() => log('Maximized HWND ' + hwnd + ' to fill workspace.', 'success'));\n    }\n\n    async function inspectElementsSelectedWindow() {\n      const hwnd = document.getElementById('desktop-window-select')?.value;\n      if (!hwnd) return;\n      const drawer = document.getElementById('desktop-elements-drawer');\n      const chips = document.getElementById('desktop-elements-chips');\n      drawer.style.display = 'block';\n      chips.innerHTML = '<span style=\"color: var(--text-dim); font-size: 11px;\">Scanning UIAutomation tree...</span>';\n      try {\n        const res = await fetch('/api/desktop/elements?hwnd=' + hwnd);\n        const data = await res.json();\n        if (data.success && data.elements) {\n          chips.innerHTML = data.elements.map(el => `\n            <button class=\"secondary\" style=\"padding: 2px 7px; font-size: 10px;\" onclick=\"clickElement('${el.runtimeId}')\">${el.name || el.controlType}</button>\n          `).join('');\n        }\n      } catch (e) {\n        chips.innerHTML = '<span style=\"color: var(--danger); font-size: 11px;\">Elements scan failed.</span>';\n      }\n    }\n\n    async function ocrSelectedWindow() {\n      const hwnd = document.getElementById('desktop-window-select')?.value;\n      if (!hwnd) return;\n      const drawer = document.getElementById('desktop-ocr-drawer');\n      const chips = document.getElementById('desktop-ocr-chips');\n      const countEl = document.getElementById('desktop-ocr-count');\n      drawer.style.display = 'block';\n      chips.innerHTML = '<span style=\"color: var(--text-dim); font-size: 11px;\">Running WinRT OCR...</span>';\n      try {\n        const res = await fetch('/api/desktop/ocr', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ hwnd })\n        });\n        const data = await res.json();\n        if (data.success && data.words) {\n          countEl.textContent = data.words.length + ' words detected';\n          chips.innerHTML = data.words.map(w => `\n            <button class=\"secondary\" style=\"padding: 2px 6px; font-size: 10px;\" onclick=\"clickOcrWord(${w.x}, ${w.y})\">${w.text}</button>\n          `).join('');\n          log('WinRT OCR complete: ' + data.words.length + ' words.', 'success');\n        }\n      } catch (e) {\n        chips.innerHTML = '<span style=\"color: var(--danger); font-size: 11px;\">OCR failed.</span>';\n      }\n    }\n\n    function sendDesktopKeys() {\n      const input = document.getElementById('desktop-keys-input');\n      const keys = input.value;\n      if (!keys) return;\n      const hwnd = document.getElementById('desktop-window-select')?.value;\n      fetch('/api/desktop/keys', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ hwnd, keys })\n      }).then(() => {\n        log('Sent keystrokes: \"' + keys + '\"', 'success');\n        input.value = '';\n      });\n    }\n\n    function scrollWindow(delta) {\n      const hwnd = document.getElementById('desktop-window-select')?.value;\n      fetch('/api/desktop/scroll', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ hwnd, delta })\n      });\n    }\n\n    // --- Chrome CDP Tabs ---\n    async function refreshWebTabs() {\n      const select = document.getElementById('web-tab-select');\n      if (!select) return;\n      select.innerHTML = '<option value=\"\">Scanning Chrome tabs...</option>';\n      try {\n        const res = await fetch('/api/web/tabs');\n        const data = await res.json();\n        if (data.success && data.tabs) {\n          select.innerHTML = data.tabs.map(t => `<option value=\"${t.id}\">${t.title}</option>`).join('');\n          onWebTabSelected();\n        }\n      } catch (e) {\n        select.innerHTML = '<option value=\"\">Scan failed</option>';\n      }\n    }\n\n    function onWebTabSelected() {\n      const select = document.getElementById('web-tab-select');\n      const details = document.getElementById('web-tab-details');\n      if (!select || !details) return;\n      const text = select.options[select.selectedIndex]?.text || 'No tab selected';\n      details.textContent = text;\n    }\n\n    function sendWebType() {\n      const input = document.getElementById('web-keys-input');\n      const text = input.value;\n      if (!text) return;\n      const tabId = document.getElementById('web-tab-select')?.value;\n      fetch('/api/web/type', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ tabId, text })\n      }).then(() => {\n        log('Typed into web tab: \"' + text + '\"', 'success');\n        input.value = '';\n      });\n    }\n\n    // --- Services Watchdog & Self-Healing ---\n    async function refreshServices() {\n      const grid = document.getElementById('services-grid');\n      if (!grid) return;\n      try {\n        const res = await fetch('/api/services');\n        const data = await res.json();\n        if (data.services) {\n          grid.innerHTML = data.services.map(s => `\n            <div style=\"background: rgba(0,0,0,0.3); border: 1px solid var(--card-border); padding: 8px 12px; border-radius: var(--radius-sm); display: flex; justify-content: space-between; align-items: center;\">\n              <div>\n                <strong style=\"font-size: 12px; color: #fff;\">${s.name}</strong>\n                <div style=\"font-size: 10px; color: var(--text-dim);\">PID: ${s.pid || '--'}</div>\n              </div>\n              <span style=\"font-size: 10px; padding: 2px 6px; border-radius: 4px; font-weight: 700; background: ${s.running ? 'var(--success-dim)' : 'var(--danger-dim)'}; color: ${s.running ? 'var(--success)' : 'var(--danger)'};\">${s.running ? 'HEALTHY' : 'DOWN'}</span>\n            </div>\n          `).join('');\n        }\n      } catch (e) {}\n    }\n\n    function autoHealServices() {\n      log('Running Sovereign Service Watchdog auto-heal loop...', 'warning');\n      fetch('/api/services/heal', { method: 'POST' }).then(() => {\n        log('Service watchdog auto-healing cycle completed.', 'success');\n        refreshServices();\n      });\n    }\n\n    // --- Workspace Layouts ---\n    function applyWorkspaceLayout(layout) {\n      log('Applying Workspace Layout: \"' + layout + '\"...', 'accent');\n      fetch('/api/workspace/layout', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ layout })\n      }).then(() => log('Workspace layout \"' + layout + '\" applied.', 'success'));\n    }\n\n    // --- Windows Clipboard Bridge ---\n    async function readClipboardText() {\n      try {\n        const res = await fetch('/api/clipboard');\n        const data = await res.json();\n        const input = document.getElementById('clipboard-text-input');\n        if (input && data.text) input.value = data.text;\n        log('Read from Windows clipboard: ' + (data.text?.length || 0) + ' chars', 'success');\n      } catch (e) {}\n    }\n\n    function writeClipboardText() {\n      const text = document.getElementById('clipboard-text-input')?.value;\n      if (!text) return;\n      fetch('/api/clipboard', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ text })\n      }).then(() => log('Text set into Windows Clipboard!', 'success'));\n    }\n\n    function clearClipboardText() {\n      fetch('/api/clipboard/clear', { method: 'POST' }).then(() => {\n        document.getElementById('clipboard-text-input').value = '';\n        log('Windows clipboard cleared.', 'success');\n      });\n    }\n\n    // --- PDH Disk Sentinel ---\n    async function scanDiskSentinel() {\n      try {\n        const res = await fetch('/api/disk-sentinel');\n        const data = await res.json();\n        if (data.success) {\n          document.getElementById('comp-disk-queue').textContent = data.metrics.queueDepth;\n          document.getElementById('comp-disk-pct').textContent = data.metrics.activePercentage + '%';\n          document.getElementById('comp-disk-reads').textContent = data.metrics.readsPerSec + '/s';\n          log('PDH Spindle Sentinel scanned: Queue Depth ' + data.metrics.queueDepth, 'success');\n        }\n      } catch (e) {}\n    }\n\n    // --- Memory Vault & Galaxy ---\n    let isGalaxyView = false;\n    function toggleMemoryView() {\n      isGalaxyView = !isGalaxyView;\n      const galaxy = document.getElementById('memory-galaxy-container');\n      const vault = document.getElementById('memory-vault-container');\n      const btn = document.getElementById('btnToggleMemoryView');\n      if (isGalaxyView) {\n        galaxy.style.display = 'block';\n        vault.style.display = 'none';\n        btn.textContent = '📋 List View';\n        initGalaxyCanvas();\n      } else {\n        galaxy.style.display = 'none';\n        vault.style.display = 'flex';\n        btn.textContent = '🌌 Galaxy Map';\n      }\n    }\n\n    async function refreshMemories() {\n      const container = document.getElementById('memory-vault-container');\n      if (!container) return;\n      try {\n        const res = await fetch('/api/memories');\n        const data = await res.json();\n        if (data.memories) {\n          container.innerHTML = data.memories.slice(0, 10).map(m => `\n            <div style=\"background: rgba(0,0,0,0.3); border: 1px solid var(--card-border); padding: 8px 12px; border-radius: var(--radius-sm);\">\n              <div style=\"display: flex; justify-content: space-between; margin-bottom: 4px;\">\n                <strong style=\"color: var(--purple); font-size: 12px;\">${m.concept}</strong>\n                <span style=\"font-size: 10px; color: var(--text-dim); font-family: var(--font-mono);\">${m.domain}</span>\n              </div>\n              <div style=\"font-size: 11px; color: var(--text-muted);\">${m.content}</div>\n            </div>\n          `).join('');\n        }\n      } catch (e) {}\n    }\n\n    function searchMemories() {\n      const q = document.getElementById('memory-search-input')?.value;\n      const cat = document.getElementById('memory-cat-select')?.value;\n      log('Recalling from .hmb vault: \"' + q + '\"...', 'purple');\n      fetch('/api/memories/search?q=' + encodeURIComponent(q) + '&domain=' + encodeURIComponent(cat))\n        .then(r => r.json())\n        .then(data => {\n          log('Recall yielded ' + (data.results?.length || 0) + ' memory anchors.', 'success');\n        });\n    }\n\n    function rememberAnchor() {\n      const concept = document.getElementById('remember-concept-input')?.value;\n      const content = document.getElementById('remember-content-input')?.value;\n      if (!concept || !content) return;\n      fetch('/api/memories/remember', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ concept, content, domain: 'EPISODIC' })\n      }).then(() => {\n        log('Memory anchor \"' + concept + '\" committed to .hmb contiguous binary vault.', 'success');\n        document.getElementById('remember-concept-input').value = '';\n        document.getElementById('remember-content-input').value = '';\n        refreshMemories();\n      });\n    }\n\n    function syncHavenVault() {\n      log('Synchronizing Haven Memory Bank with ASP.NET backend...', 'purple');\n      fetch('/api/memories/sync', { method: 'POST' }).then(() => {\n        log('Haven Vault synchronization complete.', 'success');\n        refreshMemories();\n      });\n    }\n\n    // 2D Galaxy Map Canvas Simulation\n    let galaxyNodes = [];\n    async function loadGalaxyMap() {\n      try {\n        const res = await fetch('/api/memories/galaxy');\n        const data = await res.json();\n        if (data.nodes) galaxyNodes = data.nodes;\n      } catch (e) {}\n    }\n\n    function initGalaxyCanvas() {\n      const canvas = document.getElementById('galaxyCanvas');\n      if (!canvas) return;\n      const ctx = canvas.getContext('2d');\n      let angle = 0;\n      function render() {\n        ctx.fillStyle = '#020306';\n        ctx.fillRect(0, 0, canvas.width, canvas.height);\n        angle += 0.002;\n        const cx = canvas.width / 2;\n        const cy = canvas.height / 2;\n        ctx.strokeStyle = 'rgba(0, 229, 255, 0.08)';\n        ctx.beginPath(); ctx.arc(cx, cy, 120, 0, Math.PI * 2); ctx.stroke();\n        ctx.beginPath(); ctx.arc(cx, cy, 60, 0, Math.PI * 2); ctx.stroke();\n\n        (galaxyNodes.length > 0 ? galaxyNodes : [\n          { concept: 'Core Identity', x: 0, y: 0, color: '#c084fc' },\n          { concept: 'Win32 System Calls', x: 80, y: 30, color: '#00e5ff' },\n          { concept: 'Sovereign Audio', x: -70, y: 50, color: '#00ff88' },\n          { concept: 'Memory Contiguity', x: 40, y: -90, color: '#ffb700' },\n          { concept: 'Emotional Resonance', x: -60, y: -50, color: '#ff3366' }\n        ]).forEach((n, idx) => {\n          const rad = idx * 1.25 + angle;\n          const dist = 40 + (idx * 30);\n          const px = cx + Math.cos(rad) * dist;\n          const py = cy + Math.sin(rad) * dist;\n          ctx.fillStyle = n.color || '#00e5ff';\n          ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();\n          ctx.fillStyle = '#cbd5e1';\n          ctx.font = '10px monospace';\n          ctx.fillText(n.concept, px + 8, py + 3);\n        });\n        if (isGalaxyView) requestAnimationFrame(render);\n      }\n      render();\n    }\n\n    // --- Narration & Voice Toggle ---\n    let voiceEnabled = true;\n    function toggleVoice() {\n      voiceEnabled = !voiceEnabled;\n      const btn = document.getElementById('btnVoiceToggle');\n      if (btn) {\n        btn.textContent = voiceEnabled ? '🔊 VOICE: ON' : '🔇 VOICE: MUTED';\n        btn.classList.toggle('secondary', !voiceEnabled);\n      }\n    }\n\n    // --- Gemmi 4D Avatar ---\n    function animateAvatar(action) {\n      fetch('/api/gemmi/animate', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ action })\n      }).then(() => log('Avatar gesture triggered: ' + action, 'success'));\n    }\n\n    function setAvatarLocomotion(state) {\n      fetch('/api/gemmi/animate', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ state })\n      }).then(() => {\n        log('Avatar locomotion state: ' + state, 'success');\n        document.getElementById('avatar-locomotion').innerHTML = 'State: <span style=\"color: var(--accent);\">' + state + '</span>';\n      });\n    }\n\n    // --- SSE Event Stream ---\n    const evtSource = new EventSource('/api/events');\n    evtSource.onmessage = function(e) {\n      try {\n        const data = JSON.parse(e.data);\n        if (data.type === 'narration' && data.entry) {\n          const stream = document.getElementById('narration-stream');\n          const phase = document.getElementById('narration-phase');\n          if (stream) stream.textContent = data.entry.text;\n          if (phase) phase.textContent = (data.entry.phase || 'INFO').toUpperCase();\n          log('🎙️ ' + data.entry.text, 'accent');\n        }\n        if (data.type === 'bus_updated') {\n          refreshBus();\n        }\n        if (data.type === 'playbook_completed') {\n          log('Playbook \"' + data.playbook + '\" finished in ' + data.durationMs + 'ms', 'success');\n        }\n      } catch (err) {}\n    };\n\n    // Auto-init on load\n    const hash = window.location.hash.replace('#', '') || 'telemetry';\n    switchTab(hash);\n    refreshTelemetry();\n    refreshServices();\n    scanDiskSentinel();\n    setInterval(refreshTelemetry, 5000);\n    setInterval(scanDiskSentinel, 15000);\n  </script>\n</body>\n</html>\n";
